  "NAUČÍME ŤA TO,<br><span class=\"mark\">ČO ROBÍME MY</span>": "НАУЧИМ ТЕБЯ ТОМУ,<br><span class=\"mark\">ЧТО ДЕЛАЕМ САМИ</span>",
  "NEALKOHOLICKÉ<br><span class=\"mark\">NÁPOJE</span>": "БЕЗАЛКОГОЛЬНЫЕ<br><span class=\"mark\">НАПИТКИ</span>",
  "NEŽ SA<br><span class=\"mark\">PRIHLÁSIŠ</span>": "ПРЕЖДЕ ЧЕМ<br><span class=\"mark\">ЗАПИСАТЬСЯ</span>",
